// One-off setup: opt the Mudala Retirement account into the CCT asset.
// Retired credits are clawed back into this account and never move again -
// it's the permanent on-chain record of "this ton of CO2 has been claimed."
//
// NEXT_PUBLIC_RETIREMENT_ADDR / NEXT_PUBLIC_RETIREMENT_MNEMONIC must already
// be set in .env.local (a fresh account is generated by this repo's setup
// step if they aren't yet), and the account needs a small TestNet ALGO
// balance (via https://bank.testnet.algorand.network/) before opt-in works.
//
// Usage: node scripts/setup-retirement.js

require("dotenv").config({path: "./.env.local"});
const algosdk = require("algosdk");
const getAlgodClient = require("../clients/index.js");
const algotxns = require("../algorand/index.js");

(async () => {
    const network = process.env.NEXT_PUBLIC_NETWORK || "TestNet";
    const algodClient = getAlgodClient.getAlgodClient(network);
    const assetID = parseInt(process.env.NEXT_PUBLIC_FT_ASSET_ID);

    if (!process.env.NEXT_PUBLIC_RETIREMENT_MNEMONIC) {
        console.error("NEXT_PUBLIC_RETIREMENT_MNEMONIC is not set in .env.local yet.");
        process.exit(1);
    }
    const retirement = algosdk.mnemonicToSecretKey(process.env.NEXT_PUBLIC_RETIREMENT_MNEMONIC);

    const info = await algodClient.accountInformation(retirement.addr).do();
    console.log(`Retirement account: ${retirement.addr}`);
    console.log(`ALGO balance: ${info.amount / 1e6} ALGO`);

    if (info.amount < 1e5) {
        console.warn("Not funded yet. Send it a little TestNet ALGO via https://bank.testnet.algorand.network/ then re-run this script.");
        process.exit(0);
    }

    const alreadyOptedIn = info.assets.some((a) => a["asset-id"] === assetID);
    if (alreadyOptedIn) {
        console.log(`Already opted into asset ${assetID}. Nothing to do.`);
        return;
    }

    const optInTxn = await algotxns.getAssetOptInTxn(algodClient, retirement.addr, assetID);
    const signed = optInTxn.signTxn(retirement.sk);
    const {txId} = await algodClient.sendRawTransaction(signed).do();
    await algosdk.waitForConfirmation(algodClient, txId, 4);
    console.log(`Opted retirement account into asset ${assetID} (txn ${txId}). Ready to receive retired credits.`);
})().catch((err) => {
    console.error(err);
    process.exit(1);
});
